 "charTable": [
  [
   "人物",
   "人物简介"
  ],
  [
   "阿木",
   "彝族青年，阿果的未婚夫，后成长为红军侦察排排长，熟悉滇地山川民情，从私仇执念蜕变为心怀苍生的革命战士。"
  ],
  [
   "阿果",
   "彝族姑娘，阿木的未婚妻，阿细姐的妹妹，忠贞纯粹、坚韧果敢，是坚守故土、舍身传信的底层守望者代表。"
  ],
  [
   "红军王团长",
   "红军主力指挥员，沉稳坚毅、果敢睿智，统筹全盘渡江作战部署，兼具军人铁血与家国温情。"
  ],
  [
   "小马哥",
   "年轻红军战士，阿木专属通信员，机敏灵动、热血纯粹，是青年红军战士群像缩影。"
  ],
  [
   "燕南云",
   "红军女战士，冷静果敢、心思缜密，专职情报侦察、敌后渗透、物资截获，战力与胆识兼备。"
  ],
  [
   "阿细姐",
   "阿果的姐姐，淳朴善良的彝寨民众代表；其母亦死于刘矬子之手，姐妹俩一同承受旧势力的压迫，见证民族隔阂消解与彝汉同心的全过程。"
  ],
  [
   "船工李老爹",
   "金沙江老牌船工，淳朴正直、明辨是非；起先畏惧“夜不渡皎平”的旧俗，终以押上身家为担保带头破例开船。"
  ],
  [
   "刘矬子",
   "受龙云委任的乡保团总，依附地方豪强替其收租囤粮、封锁渡口，凶狠贪婪、蛮横跋扈，是反动基层势力的代表。"
  ],
  [
   "苟二",
   "受雇于刘矬子的爪牙，势利狡黠、为虎作伥，依附恶势力迫害乡民、滋扰村寨、阻拦革命队伍。"
  ],
  [
   "黄副官",
   "龙云麾下副官，奉命押送云南军用地图，疏忽大意被红军截获，成就“缴获龙云云南军用地图”的历史佳话。"
  ],
  [
   "其他角色",
   "彝家猎人（背阿木下崖）、阿铁叔（寨中联络人）、彝寨老人、红军战士与侦察兵、众船工与众乡亲、团丁与滇军追兵、画外红军歌声。"
  ]
 ],
 "threads": [
  {
   "name": "阿爹的彝刀",
   "color": "#c8323f",
   "plant": "序幕，阿爹倒在血泊里，把腰间的彝刀交到他手边；刀锋在火光下泛着寒光。",
   "pay": "第三幕，他把磨了三年的彝刀塞进阿果手里——你替我拿着，就像我在你身边。",
   "note": "一把刀，串起父子与山河两重情感。"
  },
  {
   "name": "日月纹帕子",
   "color": "#c8323f",
   "plant": "第三幕，阿果把母亲留下的日月纹绣帕撕成两半，一半塞给阿木：见帕如见人。",
   "pay": "染血成证，经王团长与李老爹之手辗转；尾幕两半合成一整条带血手帕。",
   "note": "两半帕子，是恋人之间最重的托付。"
  },
  {
   "name": "真假油布包",
   "color": "#b98b3a",
   "plant": "第三幕月下，阿木掏出两个一模一样的油布包，一真一假分给两人。",
   "pay": "情报分毫不差，四幕渡口接应成功。",
   "note": "一真一假两份图，是第三幕的机与情。"
  },
  {
   "name": "刘矬子的鞭子",
   "color": "#6b6f76",
   "plant": "杀父之仇，三年执念。",
   "pay": "崖上对峙，被击毙沉江。",
   "note": "从序幕的火塘一直牵到第四幕的江边。"
  },
  {
   "name": "夜不渡皎平",
   "color": "#6b6f76",
   "plant": "祖辈旧俗，三十七位船工无人敢开夜船。",
   "pay": "李老爹押上身家带头破俗，六只木船昼夜轮转。",
   "note": "一条旧规矩，被人心生生改写。"
  },
  {
   "name": "三十七位船工的名字",
   "color": "#589C95",
   "plant": "第四幕，三十七位各族船工上了船，在江面上一轮接一轮地划。",
   "pay": "护送三万红军闯过天险；尾幕石碑上刻下他们的名字。",
   "note": "有人有大名，有人只有俗名和绰号，都是山河不破的底气。"
  }
 ],
